import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long inputNumber = scanner.nextLong();

        long[] baseValues = new long[19];
        baseValues[0] = 1;
        for (int i = 1; i <= 18; i++) {
            baseValues[i] = baseValues[i - 1] * 10;
        }

        long[] cumulative = new long[19];
        cumulative[0] = 0;
        for (int i = 1; i <= 18; i++) {
            cumulative[i] = cumulative[i - 1] + baseValues[i];
        }

        int maxIndex = 1;
        while (maxIndex <= 18 && cumulative[maxIndex] <= inputNumber) {
            maxIndex++;
        }
        maxIndex--;

        final int[] minCost = {Integer.MAX_VALUE};

        recurse(maxIndex, inputNumber, 0, baseValues, minCost);

        System.out.println(minCost[0]);
        scanner.close();
    }

    private static void recurse(int idx, long num, int cost, long[] baseValues, int[] minCost) {
        if (num == 0) {
            if (cost < minCost[0]) {
                minCost[0] = cost;
            }
            return;
        }
        if (idx == 0) return;

        long val = baseValues[idx];
        int i;
        for (i = -10; i * val <= num; i++);
        recurse(idx - 1, num - (i - 1) * val, cost + Math.abs(i - 1) * (idx + 1), baseValues, minCost);
        recurse(idx - 1, num - i * val, cost + Math.abs(i) * (idx + 1), baseValues, minCost);
    }
}
